# ----------------------------------------------------------------------
# Model
# ----------------------------------------------------------------------
model = pulp.LpProblem("RegionalPowerDistribution", pulp.LpMinimize)

# Decision variables: x[p,h] = MW sent from plant p to hub h
x = pulp.LpVariable.dicts("x", (plants, hubs), lowBound=0, cat="Continuous")

# ----------------------------------------------------------------------
# R1: Plant generation capacity constraints
# ----------------------------------------------------------------------
for p in plants:
    model += (
        pulp.lpSum(x[p][h] for h in hubs) <= gen_capacity[p],
        f"R1_{p}"
    )

# ----------------------------------------------------------------------
# R2: Hub demand satisfaction constraints
# ----------------------------------------------------------------------
for h in hubs:
    model += (
        pulp.lpSum(x[p][h] for p in plants) == hub_requirement[h],
        f"R2_{h}"
    )

# ----------------------------------------------------------------------
# R3: Transmission line capacity constraints
# ----------------------------------------------------------------------
for p in plants:
    for h in hubs:
        model += (
            x[p][h] <= line_capacity[p][h],
            f"R3_{p}_{h}"
        )

# ----------------------------------------------------------------------
# R4: Non‑negativity constraints (named explicitly)
# ----------------------------------------------------------------------
for p in plants:
    for h in hubs:
        model += (
            x[p][h] >= 0,
            f"R4_{p}_{h}"
        )

# ----------------------------------------------------------------------
# Objective: Minimize total transmission cost
# ----------------------------------------------------------------------
model += pulp.lpSum(
    transmission_cost[p][h] * x[p][h] for p in plants for h in hubs
), "Total_Transmission_Cost"

# ----------------------------------------------------------------------
# Solve
# ----------------------------------------------------------------------
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# ----------------------------------------------------------------------
# Output
# ----------------------------------------------------------------------
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total Cost: {pulp.value(model.objective)}\n")

print("Optimal flows (MW):")
for p in plants:
    for h in hubs:
        flow = x[p][h].varValue
        if flow is not None and flow > 0:
            print(f"  {p} -> {h}: {flow:.2f}")
